const clipSplit = ref(clip.value.split(' '))

const r = () => useRandomInt(-5, 5)

const setRectClip = () => {
    const { width: w, height: h } = rectClip.value.getBBox()
    width.value = 1 / w
    height.value = 1 / h
}

const setNewRectClip = () => {
    return clipSplit.value
        .map((it: any) =>
            !isNaN(it) && !isNaN(parseFloat(it))
                ? `${parseFloat(it) + r()}`
                : it
        )
        .join(' ')
}

const onResize = () => {
    setRectClip()
}

onMounted(() => {
    setRectClip()
    window.addEventListener('resize', onResize, true)
    clip.value = setNewRectClip()

    setInterval(() => {
        clip.value = setNewRectClip()
    }, 1000)

